// Title: Preserve Excel Cell Comments When Exporting to PDF with AspNet.Cells for .NET (C#)
// Description: Demonstrates how to keep Excel cell comments visible in a PDF generated by Aspose.Cells. The example sets PageSetup.PrintComments to PrintInPlace and saves the workbook using PdfSaveOptions, ensuring comments are retained in the output file.
// Keywords: Aspose.Cells | C# | PDF export | cell comments | PrintComments | PrintInPlace | PdfSaveOptions | retain comments | export Excel to PDF | preserve comments PDF
// Common Searches: how to keep Excel comments in PDF using Aspose.Cells | Aspose.Cells export to PDF with comments displayed | PrintComments PrintInPlace PDF Aspose.Cells C# | retain cell notes when saving workbook as PDF | Aspose.Cells PDFSaveOptions comment retention
// Developer Intent: Generate a PDF from an Excel workbook while preserving any cell comments so they appear in the final document.
// Use Cases: Create stakeholder reports that include reviewer notes embedded as cell comments. | Distribute spreadsheets with annotation footnotes in PDF format for legal or compliance review. | Produce PDF invoices or statements where explanatory comments must be visible to the recipient.
// AI Prompts: Show me a C# snippet that exports an Aspose.Cells workbook to PDF with cell comments retained. | Explain how the PrintComments property affects PDF output and how to verify comments are included. | Provide a step‑by‑step guide to configure PdfSaveOptions for comment preservation in Aspose.Cells.

using System;
using Aspose.Cells;

// Demonstrates how to keep Excel cell comments visible in a PDF generated by Aspose.Cells. The example sets PageSetup.PrintComments to PrintInPlace and saves the workbook using PdfSaveOptions, ensuring comments are retained in the output file.
class PreserveCommentsPdf
{
    static void Main()
    {
        // Create a new workbook and get the first worksheet
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];

        // Add some data to a cell
        sheet.Cells["A1"].PutValue("Sample Data");

        // Add a comment to the same cell
        int commentIndex = sheet.Comments.Add("A1");
        Comment comment = sheet.Comments[commentIndex];
        comment.Note = "This comment will appear in the PDF";

        // Enable printing of comments in place (they will be retained in the PDF)
        sheet.PageSetup.PrintComments = PrintCommentsType.PrintInPlace;

        // Create PDF save options (default options are sufficient for comment retention)
        PdfSaveOptions pdfOptions = new PdfSaveOptions();

        // Save the workbook as a PDF file with the specified options
        workbook.Save("PreserveComments.pdf", pdfOptions);
    }
}
